#!/usr/bin/env node
/**
 * Rasterises Natural Earth's 50m land polygons into a compact equirectangular
 * bitmask, and writes it as a TypeScript module.
 *
 * Run once, committed as source: `npm run build:landmask`. The generated file
 * has no runtime dependency, so world-atlas and topojson-client stay devDeps
 * and never reach the bundle.
 *
 * 720×360 is one cell per half-degree — far finer than the ~3° spacing of 3,600
 * points on a sphere, so the coastline is the limiting factor, not the raster.
 */
import { writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'

import { feature } from 'topojson-client'

const require = createRequire(import.meta.url)
const topology = require('world-atlas/land-50m.json')

const WIDTH = 720
const HEIGHT = 360

const land = feature(topology, topology.objects.land)

/** Every ring of every polygon, flattened, with a precomputed bounding box. */
const rings = []
for (const geom of land.features ?? [land]) {
  const polygons =
    geom.geometry.type === 'Polygon' ? [geom.geometry.coordinates] : geom.geometry.coordinates
  for (const polygon of polygons) {
    for (const ring of polygon) {
      let minX = Infinity
      let maxX = -Infinity
      let minY = Infinity
      let maxY = -Infinity
      for (const [x, y] of ring) {
        if (x < minX) minX = x
        if (x > maxX) maxX = x
        if (y < minY) minY = y
        if (y > maxY) maxY = y
      }
      rings.push({ ring, minX, maxX, minY, maxY })
    }
  }
}

console.log(`rings: ${rings.length}`)

/** Standard ray-casting point-in-polygon. */
function inRing(ring, x, y) {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i]
    const [xj, yj] = ring[j]
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside
  }
  return inside
}

// Bucket rings by latitude band so each cell only tests rings that can contain it.
const BANDS = 180
const bands = Array.from({ length: BANDS }, () => [])
for (const r of rings) {
  const lo = Math.max(0, Math.floor(((r.minY + 90) / 180) * BANDS))
  const hi = Math.min(BANDS - 1, Math.floor(((r.maxY + 90) / 180) * BANDS))
  for (let b = lo; b <= hi; b++) bands[b].push(r)
}

const bytes = new Uint8Array((WIDTH * HEIGHT) / 8)
let landCells = 0

for (let row = 0; row < HEIGHT; row++) {
  // Cell centre latitude, north at row 0.
  const lat = 90 - ((row + 0.5) / HEIGHT) * 180
  const band = Math.min(BANDS - 1, Math.max(0, Math.floor(((lat + 90) / 180) * BANDS)))
  const candidates = bands[band]

  for (let col = 0; col < WIDTH; col++) {
    const lon = ((col + 0.5) / WIDTH) * 360 - 180

    // A point is land when it is inside an odd number of rings, which handles
    // lakes and inland seas punched out of a continent.
    let inside = false
    for (const r of candidates) {
      if (lon < r.minX || lon > r.maxX || lat < r.minY || lat > r.maxY) continue
      if (inRing(r.ring, lon, lat)) inside = !inside
    }

    if (inside) {
      const bit = row * WIDTH + col
      bytes[bit >> 3] |= 1 << (bit & 7)
      landCells += 1
    }
  }
  if (row % 60 === 0) process.stdout.write(`  row ${row}/${HEIGHT}\n`)
}

const pct = ((landCells / (WIDTH * HEIGHT)) * 100).toFixed(1)
console.log(`land cells: ${landCells} (${pct}% of the grid)`)

const out = `// GENERATED by scripts/build-landmask.mjs — do not edit.
//
// Natural Earth 50m land polygons, rasterised to a ${WIDTH}×${HEIGHT} equirectangular
// bitmask (row 0 = 90°N, column 0 = 180°W). One bit per cell, LSB first, base64.
//
// Regenerate with: npm run build:landmask

export const LAND_WIDTH = ${WIDTH}
export const LAND_HEIGHT = ${HEIGHT}

const PACKED =
  '${Buffer.from(bytes).toString('base64')}'

let cache: Uint8Array | null = null

/** Decodes the mask once, on first use. */
export function landMask(): Uint8Array {
  if (cache) return cache
  const binary = atob(PACKED)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  cache = bytes
  return cache
}

/** True when the cell at (col, row) is land. */
export function isLand(mask: Uint8Array, col: number, row: number): boolean {
  const bit = row * LAND_WIDTH + col
  return (mask[bit >> 3] & (1 << (bit & 7))) !== 0
}
`

writeFileSync('src/three/geometry/landmask.ts', out)
console.log(`wrote src/three/geometry/landmask.ts (${(out.length / 1024).toFixed(1)} kB)`)
